  baseHp: number;
  baseAtk: number;
  baseDef: number;
  baseSpd: number;
  skillName: string;
  skillDesc: string;
  pokemonName: string;
  pokedexNumber: string;
  pokeId: number;
  region: PokemonRegion;
  showdownName: string;
  types: string[];
  imageUrl: string;
