export const ALL_POKEMON_LIST: PetSpeciesDef[] = Object.values(POKEMON_CATALOG);

const LEGACY_PET_MAP: Record<string, string> = {
  dragon: "charizard",
  buho: "noctowl",
  zorro: "vulpix",
  shiba: "growlithe",
  perro: "growlithe",
  gato: "meowth",
};

export function getPokemonById(idOrKey: string): PetSpeciesDef | undefined {
  let clean = idOrKey.toLowerCase().trim().replace(/[-\s]/g, "_");
  if (LEGACY_PET_MAP[clean]) clean = LEGACY_PET_MAP[clean];
  if (POKEMON_CATALOG[clean]) return POKEMON_CATALOG[clean];
  const num = parseInt(idOrKey.replace(/#/g, ""), 10);
  if (!isNaN(num)) {
    return ALL_POKEMON_LIST.find((p) => p.pokeId === num);
  }
  return ALL_POKEMON_LIST.find(
    (p) => p.name.toLowerCase() === clean || p.pokemonName.toLowerCase() === clean || p.id === clean
  );
}

export function getPokemonByRegion(region: PokemonRegion): PetSpeciesDef[] {
  return ALL_POKEMON_LIST.filter((p) => p.region === region);
}
